#include <stdio.h>
#include <stdlib.h>
typedef struct Node { int data; struct Node *left, *right; } Node;
Node* insert(Node* root, int val) { if(!root) { Node* nn=malloc(sizeof(Node)); nn->data=val; nn->left=nn->right=NULL; return nn; } if(val<root->data) root->left=insert(root->left, val); else root->right=insert(root->right, val); return root; }
int first=1;
void pre(Node* root) { if(!root) return; printf("%s%d", first?"":" ", root->data); first=0; pre(root->left); pre(root->right); }
int main() { int n, v; if(scanf("%d", &n)!=1) return 0; Node* root=NULL; for(int i=0; i<n; i++) { scanf("%d", &v); root=insert(root, v); } if(!root) { printf("Empty\n"); return 0; } first=1; pre(root); printf("\n"); return 0; }

